INSERT INTO posts (title,content,author,phone,product,password_hash,is_secret,reply,replied_at,created_at) VALUES
('설치 가능 지역 확인 요청','기존에 사용하던 번호를 그대로 유지할 수 있는지 문의드립니다. 사무실 이전 예정이라 이전 설치 절차도 안내 부탁드립니다.','윤혜림','01082916270','KT 기업용 인터넷','seed',0,'안녕하세요, KT 공식가입센터입니다. 문의주신 내용 확인했습니다. 해당 지역은 기가 회선 설치가 가능하며 사무실 규모에 맞춘 결합 상품을 추천드립니다. 설치까지는 신청 후 영업일 기준 3~5일 소요되며, 기업전화 결합 시 구내공사는 무료로 지원됩니다.','2026-11-05 09:40:00','2026-11-05 09:40:00'),
('기존 번호 그대로 이전 가능한가요','안녕하세요. 현재 사용 중인 회선 약정이 만료되어 KT로 이동을 검토하고 있습니다. 설치 희망 지역은 서울 구로구 인근 사무실이며, 사용 인원은 9명 정도입니다. 가능한 요금제와 설치 소요 기간, 랜공사 비용도 함께 안내 부탁드립니다.','윤수진','01087150673','KT 기업인터넷 전화','seed',0,'안녕하세요, KT 공식가입센터입니다. 설치 가능 여부 확인 결과 문제 없이 진행 가능합니다. 약정 기간과 사은 혜택까지 포함해 담당자가 곧 연락드리겠습니다.','2026-11-05 09:04:00','2026-11-05 09:04:00'),
